        shortlistGateMinCandidates: 6,
        shortlistGateMinDocs: 2,
        wikiSearchMaxResults: 5,
        wikiSnippetMaxChars: 360,
        wikiContextLimit: 5,
        webSearchMaxResults: 5,
        webSnippetMaxChars: 500,
        webFetchPageCount: 3,
